import Foundation
import Compression

// Search Indexing Service with Audit Logging
// Handles compressed document uploads for full-text search indexing

struct AuditEntry: Codable {
    let timestamp: Date
    let action: String
    let userId: String
    let details: String
}

class AuditLogger {
    private var entries: [AuditEntry] = []
    private let queue = DispatchQueue(label: "audit.logger")

    func log(action: String, userId: String, details: String) {
        queue.sync {
            let entry = AuditEntry(timestamp: Date(), action: action, userId: userId, details: details)
            entries.append(entry)
        }
    }

    func getEntries() -> [AuditEntry] {
        return queue.sync { entries }
    }
}

struct DecompressionPolicy {
    let maxCompressedSize: Int
    let maxDecompressionRatio: Double
    let chunkSize: Int
    let maxTotalOutput: Int

    static let standard = DecompressionPolicy(
        maxCompressedSize: 10 * 1024 * 1024,  // 10 MB compressed
        maxDecompressionRatio: 50.0,            // 50:1 ratio
        chunkSize: 65536,                       // 64 KB chunks
        maxTotalOutput: 500 * 1024 * 1024       // 500 MB total
    )
}

class StreamingDecompressor {
    private let policy: DecompressionPolicy
    private let auditLogger: AuditLogger

    init(policy: DecompressionPolicy, auditLogger: AuditLogger) {
        self.policy = policy
        self.auditLogger = auditLogger
    }

    /// Validates compressed data against policy before full decompression
    func validateAndDecompress(compressedData: Data, userId: String, globalBudget: GlobalDecompressionBudget) throws -> Data {
        // Phase 1: Check compressed size
        guard compressedData.count <= policy.maxCompressedSize else {
            auditLogger.log(action: "REJECTED", userId: userId, details: "Compressed size \(compressedData.count) exceeds limit")
            throw DecompressionError.compressedSizeTooLarge
        }

        auditLogger.log(action: "DECOMPRESS_START", userId: userId, details: "Size: \(compressedData.count)")

        // Phase 2: Streaming decompression with ratio monitoring
        let decompressed = try streamDecompress(compressedData: compressedData, userId: userId, globalBudget: globalBudget)

        auditLogger.log(action: "DECOMPRESS_COMPLETE", userId: userId, details: "Output: \(decompressed.count) bytes")
        return decompressed
    }

    private func streamDecompress(compressedData: Data, userId: String, globalBudget: GlobalDecompressionBudget) throws -> Data {
        var outputBuffer = Data()
        let inputSize = compressedData.count

        // Use Apple's Compression framework for streaming
        let bufferSize = policy.chunkSize
        var decodedChunks = 0

        try compressedData.withUnsafeBytes { rawBufferPointer in
            guard let baseAddress = rawBufferPointer.baseAddress else {
                throw DecompressionError.invalidData
            }

            let sourcePtr = baseAddress.assumingMemoryBound(to: UInt8.self)
            var sourceIndex = 0
            let destinationBuffer = UnsafeMutablePointer<UInt8>.allocate(capacity: bufferSize)
            defer { destinationBuffer.deallocate() }

            let stream = UnsafeMutablePointer<compression_stream>.allocate(capacity: 1)
            defer { stream.deallocate() }

            var status = compression_stream_init(stream, COMPRESSION_STREAM_DECODE, COMPRESSION_ZLIB)
            guard status != COMPRESSION_STATUS_ERROR else {
                throw DecompressionError.invalidData
            }
            defer { compression_stream_destroy(stream) }

            stream.pointee.src_ptr = sourcePtr
            stream.pointee.src_size = inputSize
            stream.pointee.dst_ptr = destinationBuffer
            stream.pointee.dst_size = bufferSize

            repeat {
                status = compression_stream_process(stream, 0)

                switch status {
                case COMPRESSION_STATUS_OK, COMPRESSION_STATUS_END:
                    let outputSize = bufferSize - stream.pointee.dst_size
                    outputBuffer.append(destinationBuffer, count: outputSize)
                    decodedChunks += 1

                    // Ratio check against original compressed input
                    let currentRatio = Double(outputBuffer.count) / Double(max(inputSize, 1))

                    if currentRatio > policy.maxDecompressionRatio {
                        auditLogger.log(action: "RATIO_EXCEEDED", userId: userId, details: "Ratio: \(currentRatio)")
                        throw DecompressionError.ratioExceeded
                    }

                    if outputBuffer.count > policy.maxTotalOutput {
                        auditLogger.log(action: "SIZE_EXCEEDED", userId: userId, details: "Output: \(outputBuffer.count)")
                        throw DecompressionError.outputSizeTooLarge
                    }

                    // Global budget check across ALL decompression operations
                    guard globalBudget.consume(bytes: outputSize) else {
                        auditLogger.log(action: "GLOBAL_BUDGET_EXCEEDED", userId: userId, details: "Total decompressed across all layers exceeded limit")
                        throw DecompressionError.globalBudgetExceeded
                    }

                    stream.pointee.dst_ptr = destinationBuffer
                    stream.pointee.dst_size = bufferSize

                case COMPRESSION_STATUS_ERROR:
                    throw DecompressionError.invalidData
                default:
                    break
                }
            } while status == COMPRESSION_STATUS_OK
        }

        return outputBuffer
    }
}

/// Thread-safe global budget that tracks total decompression across all nested layers
class GlobalDecompressionBudget {
    private let maxTotalBytes: Int
    private var consumed: Int = 0
    private let lock = NSLock()

    init(maxTotalBytes: Int) {
        self.maxTotalBytes = maxTotalBytes
    }

    /// Returns false if budget would be exceeded
    func consume(bytes: Int) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let newTotal = consumed + bytes
        guard newTotal <= maxTotalBytes && newTotal >= consumed else {
            return false
        }
        consumed = newTotal
        return true
    }

    var remaining: Int {
        lock.lock()
        defer { lock.unlock() }
        return maxTotalBytes - consumed
    }
}

enum DecompressionError: Error {
    case compressedSizeTooLarge
    case ratioExceeded
    case outputSizeTooLarge
    case invalidData
    case nestedArchiveDepthExceeded
    case globalBudgetExceeded
}

struct DocumentEntry {
    let id: String
    let content: String
    let metadata: [String: String]
}

class SearchIndexingService {
    private let decompressor: StreamingDecompressor
    private let auditLogger: AuditLogger
    private var index: [String: [DocumentEntry]] = [:]
    private let maxRecursionDepth: Int
    private let globalBudgetLimit: Int

    init(auditLogger: AuditLogger, policy: DecompressionPolicy = .standard, maxRecursionDepth: Int = 3) {
        self.auditLogger = auditLogger
        self.decompressor = StreamingDecompressor(policy: policy, auditLogger: auditLogger)
        self.maxRecursionDepth = maxRecursionDepth
        // Global budget: total decompressed output across ALL nesting levels cannot exceed 500MB
        self.globalBudgetLimit = 500 * 1024 * 1024
    }

    /// Process uploaded archive containing documents to index
    func processUpload(compressedPayload: Data, userId: String) throws -> Int {
        // Create a fresh global budget for this entire upload operation
        let globalBudget = GlobalDecompressionBudget(maxTotalBytes: globalBudgetLimit)

        let decompressed = try decompressor.validateAndDecompress(
            compressedData: compressedPayload, userId: userId, globalBudget: globalBudget
        )

        // Parse the decompressed content as a simple archive format
        // Format: [4-byte entry count][entries...]
        // Each entry: [4-byte name len][name][4-byte content len][content]
        let documents = try parseArchive(data: decompressed, userId: userId, currentDepth: 0, globalBudget: globalBudget)

        for doc in documents {
            indexDocument(doc)
        }

        auditLogger.log(action: "INDEX_COMPLETE", userId: userId, details: "Indexed \(documents.count) documents")
        return documents.count
    }

    private func parseArchive(data: Data, userId: String, currentDepth: Int, globalBudget: GlobalDecompressionBudget) throws -> [DocumentEntry] {
        // Depth check for nested archives
        guard currentDepth <= maxRecursionDepth else {
            auditLogger.log(action: "DEPTH_EXCEEDED", userId: userId, details: "Depth: \(currentDepth)")
            throw DecompressionError.nestedArchiveDepthExceeded
        }

        var documents: [DocumentEntry] = []
        var offset = 0

        guard data.count >= 4 else { return [] }
        let entryCount = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self) }
        offset += 4

        for _ in 0..<entryCount {
            guard offset + 4 <= data.count else { break }
            let nameLen = Int(data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self) })
            offset += 4

            guard offset + nameLen <= data.count else { break }
            let name = String(data: data.subdata(in: offset..<offset+nameLen), encoding: .utf8) ?? ""
            offset += nameLen

            guard offset + 4 <= data.count else { break }
            let contentLen = Int(data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self) })
            offset += 4

            guard offset + contentLen <= data.count else { break }
            let contentData = data.subdata(in: offset..<offset+contentLen)
            offset += contentLen

            // Check if this entry is itself a compressed archive (nested)
            if name.hasSuffix(".zarchive") {
                // SAFE: Uses shared globalBudget across all nesting levels
                // Total decompression output is bounded regardless of nesting depth
                let nestedDecompressed = try decompressor.validateAndDecompress(
                    compressedData: contentData, userId: userId, globalBudget: globalBudget
                )
                let nestedDocs = try parseArchive(data: nestedDecompressed, userId: userId, currentDepth: currentDepth + 1, globalBudget: globalBudget)
                documents.append(contentsOf: nestedDocs)
            } else {
                let content = String(data: contentData, encoding: .utf8) ?? ""
                documents.append(DocumentEntry(id: UUID().uuidString, content: content, metadata: ["name": name]))
            }
        }

        return documents
    }

    private func indexDocument(_ doc: DocumentEntry) {
        let words = doc.content.lowercased().split(separator: " ").map(String.init)
        for word in words {
            index[word, default: []].append(doc)
        }
    }

    func search(query: String) -> [DocumentEntry] {
        let terms = query.lowercased().split(separator: " ").map(String.init)
        var results: [DocumentEntry] = []
        for term in terms {
            if let docs = index[term] {
                results.append(contentsOf: docs)
            }
        }
        return results
    }
}
